seal_code = #{sealCode}, seal_name = #{sealName}, seal_type = #{sealType}, seal_image_path = #{sealImagePath}, seal_image_data = #{sealImageData}, authorize_user_id = #{authorizeUserId}, authorize_time = #{authorizeTime}, expire_time = #{expireTime}, description = #{description}, status = #{status}, update_user_id = #{updateUserId}, update_time = CURRENT_TIMESTAMP
