SELECT  FROM sig_seal

    AND seal_code = #{sealCode}
    AND seal_name LIKE CONCAT('%', #{sealName}, '%')
    AND seal_type = #{sealType}
    AND authorize_user_id = #{authorizeUserId}
    AND status = #{status}

